def restock(inventory, deliveries):
    # inventory: {"apple": 3}
    # deliveries: [("apple", 2), ("pear", "4")]  (qty may be a str)
    # -> {"apple": 5, "pear": 4}
    for item, qty in deliveries:
        inventory[item] = inventory.get(item) + qty
    return inventory

solution:
def restock(inventory, deliveries):
    for item, qty in deliveries:
        inventory[item] = inventory.get(item, 0) + int(qty)
    return inventory
